import json

from sqlalchemy.orm import Session

from gpt_ai.utils import generate_gpt4_
from prompt.services import get_prompt_by_field


def get_history(db: Session, story_line: str):
    prompt_history = get_prompt_by_field(db, 'category', 'history')

    schema_history = {
        "history_generate": "string ( this is a history generated by the AI)",
    }

    text_user = prompt_history.description.replace('x_story_line', story_line)

    content_prompt = [
        {
            "role": "system",
            "content": f"{prompt_history.prompt_system} "
                       f"responde con un JSON que contenga el esquema '{schema_history}'"
        },
        {
            "role": "user",
            "content": [
                {
                    "type": "text",
                    "text": text_user
                }
            ]
        }
    ]

    history_generated = generate_gpt4_(content_prompt=content_prompt,
                                       type_text="history",
                                       max_tokens=4096, )

    return json.loads(history_generated)['history_generate']


def get_synopsis(db: Session, history: str) -> dict:
    prompt_synopsis = get_prompt_by_field(db, 'category', 'synopsis')

    schema_synopsis = {
        "synopsis_generate": "string ( this is a synopsis generated by the AI)",
        "title": "string (title of the game)",
        "prompt_image": "string (create a prompt to create an image containing the story of the game )",
    }

    content_prompt = [
        {
            "role": "system",
            "content": f"{prompt_synopsis.prompt_system} "
                       f"responde con un JSON que contenga el esquema '{schema_synopsis}'"
        },
        {
            "role": "assistant",
            "content": f"historia del juego :{history}"

        },
        {
            "role": "user",
            "content": [
                {
                    "type": "text",
                    "text": prompt_synopsis.description
                }
            ]
        }
    ]

    synopsis_generated = generate_gpt4_(content_prompt=content_prompt,
                                        type_text="synopsis",
                                        max_tokens=4096, )

    return json.loads(synopsis_generated)


def get_characters_principals(db: Session, history: str) -> dict:
    prompt_characters = get_prompt_by_field(db, 'category', 'characters_principal')

    schema_characters = {
        "characters_generate": [
            {
                "name": "string (name of the character)",
                "genre": "string (genre of the character)",
                "description": "string (description of the character)",
                "type": "string (the character types are: leading role, other, enemy, antagonist."
                        "There can only be one antagonist, one leading role, one enemy and many others. ) ",
            }
        ]
    }

    content_prompt = [
        {
            "role": "system",
            "content": f"{prompt_characters.prompt_system} "
                       f"responde con un JSON que contenga el esquema '{schema_characters}'"
        },
        {
            "role": "assistant",
            "content": f"historia del juego :{history}"

        },
        {
            "role": "user",
            "content": [
                {
                    "type": "text",
                    "text": prompt_characters.description
                }
            ]
        }
    ]

    characters_generated = generate_gpt4_(content_prompt=content_prompt,
                                          type_text="characters",
                                          max_tokens=4096)

    return json.loads(characters_generated)
